public static class ExrOracleFixtures
{
    /// <summary>True when the generated literals are present; oracle tests skip otherwise.</summary>
    public static bool Available => All.Count > 0 && Array.TrueForAll([.. All.Values], v => v.Length > 0);

    /// <summary>Formula A (plan decision 14): exactly representable in half.</summary>
    public static float FormulaA(int x, int y, int c) => ((x * 7 + y * 13 + c * 5) % 61 - 20) / 8f;

    /// <summary>Formula S, the "Smooth" fixtures: runs of equal values, exactly representable in half.</summary>
    public static float FormulaS(int x, int y, int c) => (x / 4 + y / 4 + c) % 8 / 4f;

    /// <summary>Generator B (the wdec16 fixture): distinct positive normal finite half bits.</summary>
    public static ushort GeneratorB(int x, int y, int w) => (ushort)(0x0400 + y * w + x);

    public static byte[] Bytes(string name) => Convert.FromBase64String(All[name]);

    public static IReadOnlyDictionary<string, string> All => new Dictionary<string, string>
    {
        ["RleHalf"] = RleHalf,
        ["RleHalfSmooth"] = RleHalfSmooth,
        ["RleFloat"] = RleFloat,
        ["RleFloatSmooth"] = RleFloatSmooth,
        ["ZipsHalf"] = ZipsHalf,
        ["ZipsHalfSmooth"] = ZipsHalfSmooth,
        ["ZipsFloat"] = ZipsFloat,
        ["ZipsFloatSmooth"] = ZipsFloatSmooth,
        ["ZipHalf"] = ZipHalf,
        ["ZipHalfSmooth"] = ZipHalfSmooth,
        ["ZipFloat"] = ZipFloat,
        ["ZipFloatSmooth"] = ZipFloatSmooth,
        ["PizHalf"] = PizHalf,
        ["PizHalfSmooth"] = PizHalfSmooth,
        ["PizFloat"] = PizFloat,
        ["PizFloatSmooth"] = PizFloatSmooth,
        ["TiledPizHalf"] = TiledPizHalf,
        ["TiledPizHalfSmooth"] = TiledPizHalfSmooth,
        ["Wdec16Piz"] = Wdec16Piz,
    };

    public const string RleHalf = "";
    public const string RleHalfSmooth = "";
    public const string RleFloat = "";
    public const string RleFloatSmooth = "";
    public const string ZipsHalf = "";
    public const string ZipsHalfSmooth = "";
    public const string ZipsFloat = "";
    public const string ZipsFloatSmooth = "";
    public const string ZipHalf = "";
    public const string ZipHalfSmooth = "";
    public const string ZipFloat = "";
    public const string ZipFloatSmooth = "";
    public const string PizHalf = "";
    public const string PizHalfSmooth = "";
    public const string PizFloat = "";
    public const string PizFloatSmooth = "";
    public const string TiledPizHalf = "";
    public const string TiledPizHalfSmooth = "";
    public const string Wdec16Piz = "";
    public const int Wdec16Width = 520;
}
